<script setup lang="ts">
import {reactive,ref} from 'vue';import {api} from '../api';import {useLab} from '../store';const lab=useLab();const emit=defineEmits<{close:[]}>();const profile=lab.workspace?.mysql_profile;const cfg=reactive({host:'127.0.0.1',port:3306,user:'root',password:'',database:'',tls:false,...(profile&&typeof profile==='object'&&!Array.isArray(profile)?profile:{})});const remember=ref(false);const busy=ref(false);const connected=ref(false);const preset=ref('student');const message=ref('');
async function connect(){busy.value=true;try{for(const session of ['main','A','B'])await api('mysql_connect',{config:cfg,session,remember:remember.value});connected.value=true;lab.engine='mysql';lab.workspace!.mysql_profile={host:cfg.host,port:cfg.port,user:cfg.user,database:cfg.database,tls:cfg.tls};lab.markDirty();await lab.refresh();message.value='已连接 main、A、B 三个独立会话。';lab.log(message.value);}catch(e){message.value=String(e);lab.fail(e)}finally{busy.value=false}}
async function sandbox(){busy.value=true;try{const r=await api<typeof cfg>('mysql_sandbox',{fixture:preset.value,session:'main'});cfg.database=r.database;await connect();message.value=`已创建专用沙箱 ${r.database}`;}catch(e){message.value=String(e);lab.fail(e)}finally{busy.value=false}}
async function credential(){try{cfg.password=await api<string>('credential',{config:cfg});message.value=cfg.password?'已读取保存的凭据':'没有保存的凭据';}catch(e){lab.fail(e)}}
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal" role="dialog" aria-modal="true" aria-label="MySQL 连接"><header><div><span class="eyebrow">DATABASE CONNECTION</span><h2>连接 MySQL 教学环境</h2></div><button @click="emit('close')" aria-label="关闭连接设置">×</button></header><div class="form-grid"><label>主机<input v-model="cfg.host" autocomplete="off"></label><label>端口<input v-model.number="cfg.port" type="number"></label><label>用户名<input v-model="cfg.user" autocomplete="off"></label><label>密码<input v-model="cfg.password" type="password" autocomplete="off"></label><label class="span-two">数据库（可先留空，随后新建沙箱）<input v-model="cfg.database"></label></div><label class="check"><input v-model="cfg.tls" type="checkbox">使用 TLS 并验证服务器证书</label><label class="check"><input v-model="remember" type="checkbox">将密码保存到 Windows 凭据存储（不写入工程）</label><div class="toolbar"><button @click="credential">读取保存的凭据</button><button class="primary" :disabled="busy" data-testid="mysql-connect" @click="connect">{{busy?'连接中…':'连接三个会话'}}</button></div><div class="divider"/><h3>建立隔离教学沙箱</h3><p class="muted">在当前服务器新建随机名称的数据库。已有数据库不会被清空。</p><div class="toolbar"><select v-model="preset"><option value="student">HNU Student</option><option value="hotel">Hotel</option><option value="bank">Bank（双会话推荐）</option><option value="empty">Empty Sandbox</option></select><button :disabled="busy||!connected" @click="sandbox">创建并切换</button></div><div v-if="message" class="notice">{{message}}</div></section></div></template>
